      "endVerse": 0,
      "author": "Tried By Fire",
      "authorHandle": "@TriedByFire",
      "text": "It is widely debated whether or not Jonah is a fictitious story in scripture. When we read the account, it certainly seems far-fetched. It has many themes, but the one specific theme that is harshly addressed here is the salvation of a people that this prophet, Jonah, doesn’t want to happen. To get a bit of a backstory, Jonah had been a prophet for the people of God for a good portion of time now, and he was likely living the high life. Most people knew him, and he was an asset to his community in Gathhepher.",
      "likes": 0,
