      "startVerse": 0,
      "endVerse": 0,
      "author": "Tried By Fire",
      "authorHandle": "@TriedByFire",
      "text": "I have spent a good portion of scripture, especially in the Old Testament, relaying names, and so I hope to do that justice in this setting as well. This book of the Bible is extremely short, but extremely powerful, and I think there are quite a few reasons to deem it essential to scripture.",
