      "chapter": 1,
      "verse": 0,
      "startVerse": 0,
      "endVerse": 0,
      "author": "Tried By Fire",
      "authorHandle": "@TriedByFire",
      "text": "Firstly, it gives a story of redemption. That is the biblical theme, is it not? People whom we might deem unworthy of redemption are the people that God seems to focus on the most. The Israelites were certainly unworthy of God’s attention, but they are focused on in scripture because they are the only ones on this entire planet willing to follow the Lord in their seasons. No other nation would stay the course leading to the Messiah.",
      "likes": 0,
      "isLikedByUser": false,
