      "book": "Jonah",
      "chapter": 1,
      "verse": 0,
      "startVerse": 0,
      "endVerse": 0,
      "author": "Tried By Fire",
      "authorHandle": "@TriedByFire",
      "text": "Secondly, because Jonah is a prophet, we are given some useful prophecy in the New Testament life of Christ. Everything in the prophets’ lives leads to Christ, whether you are reading from a major prophet of scripture or a minor prophet (minor because the book is short).",
      "likes": 0,
      "isLikedByUser": false,
