      "book": "Jonah",
      "chapter": 1,
      "verse": 0,
      "startVerse": 0,
      "endVerse": 0,
      "author": "Matthew 12:40",
      "authorHandle": "",
      "text": "\"For as Jonas was three days and three nights in the whale's belly; so shall the Son of man be three days and three nights in the heart of the earth.\" Matthew 12:40",
      "likes": 0,
      "isLikedByUser": false,
      "isBookmarkedByUser": false,
      "createdAt": "2026-09-23T00:00:00.000Z",
      "kind": "quote",
      "quoteStyle": "inline",
