      "chapter": 1,
      "verse": 0,
      "startVerse": 0,
      "endVerse": 0,
      "author": "2 Kings 14:25",
      "authorHandle": "",
      "text": "\"He restored the coast of Israel from the entering of Hamath unto the sea of the plain, according to the word of the LORD God of Israel, which he spake by the hand of his servant Jonah, the son of Amittai, the prophet, which was of Gathhepher.\" 2 Kings 14:25",
      "likes": 0,
      "isLikedByUser": false,
      "isBookmarkedByUser": false,
      "createdAt": "2026-09-23T00:00:00.000Z",
      "kind": "quote",
      "quoteStyle": "inline",
      "sectionId": "jonah-1-intro",
      "sectionTitle": "Introduction",
